import React, { useState, useEffect } from 'react';
import '../../styles/Hero.css';
import videoMobile from '../../assets/videos/motain.mp4';
import videoPC from '../../assets/videos/pc_video.mp4';

export default function Hero() {
  const [esMobile, setEsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handleResize = () => {
      setEsMobile(window.innerWidth < 768);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const videoSrc = esMobile ? videoMobile : videoPC;

  return (
    <section className="hero">
      <video
        key={videoSrc}
        src={videoSrc}
        autoPlay
        loop
        muted
        playsInline
        className="hero-bg"
      />
      <div className="hero-overlay" />

      <div className="hero-content hero-content-center">
      </div>

      {/* Flecha minimalista esquina inferior derecha */}
      <svg className="hero-flecha" viewBox="0 0 12 18" fill="none" xmlns="http://www.w3.org/2000/svg">
        <line x1="6" y1="0" x2="6" y2="14" stroke="white" strokeWidth="1"/>
        <polyline points="2,10 6,15 10,10" fill="none" stroke="white" strokeWidth="1"/>
      </svg>
    </section>
  );
}
